--
-- Table structure for table `flights`
--

DROP TABLE IF EXISTS `flights`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `flights` (
  `ID` bigint(20) NOT NULL,
  `AIRLINE_ID` bigint(20) DEFAULT NULL,
  `FLIGHT_NUMBER` bigint(20) DEFAULT NULL,
  `TAIL_NUMBER` text DEFAULT NULL,
  `ORIGIN_AIRPORT_ID` bigint(20) DEFAULT NULL,
  `DESTINATION_AIRPORT_ID` bigint(20) DEFAULT NULL,
  `SCHEDULED_DEPARTURE_DATE` datetime DEFAULT NULL,
  `DEPARTURE_DELAY` double DEFAULT NULL,
  `ELAPSED_TIME` double DEFAULT NULL,
  `DISTANCE` bigint(20) DEFAULT NULL,
  `ARRIVAL_DATE` datetime DEFAULT NULL,
  `ARRIVAL_DELAY` double DEFAULT NULL,
  KEY `ix_flights_ID` (`ID`),
  KEY `AIRLINE_ID` (`AIRLINE_ID`),
  KEY `ORIGIN_AIRPORT_ID` (`ORIGIN_AIRPORT_ID`),
  KEY `DESTINATION_AIRPORT_ID` (`DESTINATION_AIRPORT_ID`),
  CONSTRAINT `AIRLINE_ID` FOREIGN KEY (`AIRLINE_ID`) REFERENCES `airlines` (`ID`),
  CONSTRAINT `DESTINATION_AIRPORT_ID` FOREIGN KEY (`DESTINATION_AIRPORT_ID`) REFERENCES `airports` (`ID`),
  CONSTRAINT `ORIGIN_AIRPORT_ID` FOREIGN KEY (`ORIGIN_AIRPORT_ID`) REFERENCES `airports` (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

